  import { NotFoundError, ValidationError } from "../domain/domain-error";
  import { IdGenerator } from "../domain/id-generator";
  import { ProjectRepository } from "../domain/project-repository";
  import { Task } from "../domain/task";
  import { TaskRepository } from "../domain/task-repository";
  import { parseTaskStatus } from "../domain/task-status";
  import { CreateTaskDto } from "./dtos";

  export class CreateTaskUseCase {
    constructor(
      private readonly tasks: TaskRepository,
      private readonly projects: ProjectRepository,
      private readonly ids: IdGenerator,
    ) {}

    async execute(dto: CreateTaskDto): Promise<Task> {
      if (!(await this.projects.findById(dto.projectId))) {
        throw new NotFoundError("project not found");
      }
      if (typeof dto.title !== "string" || dto.title.trim() === "") {
        throw new ValidationError("title is required");
      }
      if (dto.description !== undefined && typeof dto.description !== "string") {
        throw new ValidationError("description must be a string");
      }
      let dueDate: Date | undefined;
      if (dto.dueDate !== undefined) {
        dueDate = new Date(dto.dueDate);
        if (Number.isNaN(dueDate.getTime())) {
          throw new ValidationError("dueDate must be a valid date");
        }
      }
      const task = new Task({
        id: this.ids.next(),
        projectId: dto.projectId,
        title: dto.title.trim(),
        description: dto.description ?? "",
        dueDate,
        status: dto.status === undefined ? "todo" : parseTaskStatus(dto.status),
      });
      await this.tasks.save(task);
      return task;
    }
  }

